// GQ has no coalesce, case or if-expression and no null literal, so "unknown"
// and the "senior"/"active" labels cannot be produced in a query.
// This returns the raw values: city is null where missing, and senior is
// true/false (null when age is missing). Map them to "unknown" and
// "senior"/"active" in the client.
query people_bands() {
    match {
        $p: Person
    }
    return {
        $p.name,
        $p.city,
        $p.age >= 65 as senior
    }
}
